// FW_RULE ([MS-FASP]). Generated by tools/idlgen; verify pointer/array tags.
type FW_RULE struct {
	PNext                             *FW_RULE `ndr:"unique"`
	WSchemaVersion                    uint16
	WszRuleId                         *ndr.WSTR `ndr:"unique"`
	WszName                           *ndr.WSTR `ndr:"unique"`
	WszDescription                    *ndr.WSTR `ndr:"unique"`
	DwProfiles                        ndr.DWORD
	Direction                         FW_DIRECTION
	WIpProtocol                       uint16
	Field                             FW_RULE_Field
	LocalAddresses                    FW_ADDRESSES
	RemoteAddresses                   FW_ADDRESSES
	LocalInterfaceIds                 FW_INTERFACE_LUIDS
	DwLocalInterfaceTypes             ndr.DWORD
	WszLocalApplication               *ndr.WSTR `ndr:"unique"`
	WszLocalService                   *ndr.WSTR `ndr:"unique"`
	Action                            FW_RULE_ACTION
	WFlags                            uint16
	WszRemoteMachineAuthorizationList *ndr.WSTR `ndr:"unique"`
	WszRemoteUserAuthorizationList    *ndr.WSTR `ndr:"unique"`
	WszEmbeddedContext                *ndr.WSTR `ndr:"unique"`
	PlatformValidityList              FW_OS_PLATFORM_LIST
	Status                            FW_RULE_STATUS
	Origin                            FW_RULE_ORIGIN_TYPE
	WszGPOName                        *ndr.WSTR `ndr:"unique"`
	Reserved                          ndr.DWORD
	PMetaData                         []FW_OBJECT_METADATA `ndr:"unique,conformant"`
	WszLocalUserAuthorizationList     *ndr.WSTR            `ndr:"unique"`
	WszPackageId                      *ndr.WSTR            `ndr:"unique"`
	WszLocalUserOwner                 *ndr.WSTR            `ndr:"unique"`
	DwTrustTupleKeywords              ndr.DWORD
	OnNetworkNames                    FW_NETWORK_NAMES
	WszSecurityRealmId                *ndr.WSTR `ndr:"unique"`
	WFlags2                           uint16
	RemoteOutServerNames              FW_NETWORK_NAMES
	WszFqbn                           *ndr.WSTR `ndr:"unique"`
	CompartmentId                     ndr.DWORD
	ProviderContextKey                guid.GUID
	RemoteDynamicKeywordAddresses     FW_DYNAMIC_KEYWORD_ADDRESS_ID_LIST
	WszPackageFamilyName              *ndr.WSTR `ndr:"unique"`
}

// FW_RULE_Field is the wIpProtocol-discriminated union ([MS-FASP] 2.2.36 FW_RULE): the port
// list arm is selected for TCP (6) and UDP (17); the ICMP type/code list for ICMPv4 (1)
// and ICMPv6 (58); all other protocols select the empty ([default]) arm. switch_type is
// WORD, so the inline discriminant Tag is a uint16 ([C706] 14.3.8).
type FW_RULE_Field struct {
	Tag            uint16                 `ndr:"switch"`
	PortsTCP       FW_RULE_PROTOCOL_PORTS `ndr:"case=6"`
	PortsUDP       FW_RULE_PROTOCOL_PORTS `ndr:"case=17"`
	V4TypeCodeList FW_ICMP_TYPE_CODE_LIST `ndr:"case=1"`
	V6TypeCodeList FW_ICMP_TYPE_CODE_LIST `ndr:"case=58"`
}

// FW_RULE_PROTOCOL_PORTS is the TCP/UDP arm shared by every FW_RULE*_Field union
// (wIpProtocol 6 or 17): the local and remote port lists ([MS-FASP] 2.2.36).
type FW_RULE_PROTOCOL_PORTS struct {
	LocalPorts  FW_PORTS
	RemotePorts FW_PORTS
}
